---@field BtnQuest                      	UnityEngine.RectTransform                                            
local UIFishPlaceNode = Class("UIFishPlaceNode")
function UIFishPlaceNode:__init() 
    ---@type FishingPlaceVo
    self._fishingPlaceVo = nil
    self._allFishVo = nil
end

function UIFishPlaceNode:__delete()
    self._fishingPlaceVo = nil
    self._allFishVo = nil
end

function UIFishPlaceNode:Awake()
end

function UIFishPlaceNode:Start()
    SetButtonAction(self.BtnDetails, Bind(self, self.OnBtnTips))
    SetButtonAction(self.BtnEnter, Bind(self, self.OnBtnEnterFishPlace))
end

function UIFishPlaceNode:Refresh(fishingPlaceVo, ind)
    if not fishingPlaceVo then
        return
    end
    CfUtils.SetActive(self.ImgNew,false)
    xTry(function()
        local storeData = CfUtils.GetLocalData("FISHING_PLACE_UNLOCKED", "")
        local t = {}
        if not string.isEmpty(storeData) then
            t = table.deserialize(storeData)
        end
        --- {['1] = 1, num = 1} example
        if t[tostring(fishingPlaceVo.id)] and checkNumber(t[tostring(fishingPlaceVo.id)]) == 1 then
            ---存在解锁的鱼场
            GameUtils.BindRedPoint(Constants.RedPointConst.PhoneFishPlaceUnlocked , self.AnimRoot, true, nil, nil, Constants.RedPointType.NEW)
        end
    end)
    self._fishingPlaceVo = fishingPlaceVo
    self:FillSelf()
end

function UIFishPlaceNode:FillSelf()
    CfUtils.FillText(self.TxtName, checkString(self._fishingPlaceVo.name))

    local isUnlock = FishingUtils.IsUnlockFishPlace(self._fishingPlaceVo.id)
    local isOpen = true

    KTool.SetActive(self.Lock, not isUnlock or not isOpen)
    KTool.SetActive(self.Unlock, isUnlock and isOpen)

    KTool.SetActive(self.OpenTime,  not isOpen and isUnlock)
    KTool.SetActive(self.Lock.transform:Find("CoditionNeed"), not isUnlock)

    if isUnlock then
        local dojo = FishingUtils.GetFishingPlaceDojo(self._fishingPlaceVo.id)
        if dojo then
            CfUtils.FillText(self.TxtNumber, "<color=#ff41b7>"..dojo.collectNum.."</color>/"..table.count(FishingUtils.GetAllFishVoByPlaceId(self._fishingPlaceVo.id)))
        end
    else
        CfUtils.FillText(self.TxtLock, FishingUtils.GetFishPlaceUnlockDesc(self._fishingPlaceVo.id))
    end
    CfUtils.FillImage(self.ImgTexture, self._fishingPlaceVo.background)

    self:FillSpecialPond()
end

--绘制活动渔场
function UIFishPlaceNode:FillSpecialPond()
    CfUtils.SetActive(self.Tip2, false)
    CfUtils.SetActive(self.Tip1, false)
    CfUtils.SetActive(self.Underway, false)
    CfUtils.SetActive(self.SymbolCanGetNode, false)

    local dojo = FishingUtils.GetFishingPlaceDojo(self._fishingPlaceVo.id)
    if not dojo then
        return
    end
    local t = checkTable(dojo.activity)
    --for k, v in pairs(t) do
        local vo = FishingUtils.GetFishActivityPlanVo(t.contentId)
        if vo then
            local isOpen = FishingUtils.IsActivityOpen(self._fishingPlaceVo.id, ConstantsFishing.ActivityType.Summer)

            if checkNumber(vo.activity) == ConstantsFishing.ActivityType.Common then
                local _t = CfUtils.Split(vo.label)
                if _t and table.count(_t) > 0 then
                    local _descT = CfUtils.Split(vo.labelDesc)
                    for _ind, _l in pairs(_t) do
                        if checkNumber(_l) > 0 then
                            local go = self["Tip".._ind]
                            CfUtils.SetActive(go, true)
                            if _descT then 
                                CfUtils.FillText(go.transform:Find("TextTip"), _descT[_ind])
                            end
                        end
                    end
                end
                self:FillTimeInfo()
            elseif checkNumber(vo.activity) == ConstantsFishing.ActivityType.Summer then
                self:FillTimeInfo()

                CfUtils.SetActive(self.SymbolCanGetNode, FishingUtils.IsShowPlaceRedPoint(self._fishingPlaceVo.id))
            elseif checkNumber(vo.activity) == ConstantsFishing.ActivityType.KingChallenge then
                CfUtils.SetActive(self.SymbolCanGetNode, FishingUtils.IsShowPlaceRedPoint(self._fishingPlaceVo.id))
            end

            CfUtils.SetActive(self.Underway, isOpen) 
            CfUtils.FillImage(self.ImgTexture, vo.backgroundChange)
        end
   -- end
end

function UIFishPlaceNode:FillTimeInfo()
    CfUtils.SetActive(self.Unlock.transform:Find("Countdown"), true) 
    CfUtils.SetActive(self.Unlock.transform:Find("TextEnter"), false) 
    self:FillTime()

    self:StartTimeDown()
end

--开始倒计时
function UIFishPlaceNode:StartTimeDown()
    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
        self._timeDown = nil
    end

    self._timeDown = CDTimerModule.GetInstance():AddCD(1, function(count, id)
        self:FillTime()
    end, CountDownTime, false, true)
end

function UIFishPlaceNode:FillTime()
    local data = FishingUtils.GetFishPlaceDojoActivityData(self._fishingPlaceVo.id)
    if not data then
        return
    end
    CfUtils.FillText(self.Unlock.transform:Find("Countdown/Text2"), CfUtils.GetTimeHMS7(checkNumber(data.remainTime)))
end


function UIFishPlaceNode:OnBtnTips()
    GameUtils.ShowCommonTipsBoardAttribute(self.BtnDetails, self._fishingPlaceVo.name, self._fishingPlaceVo.desc, true, true)
end

--进入一个渔场
function UIFishPlaceNode:OnBtnEnterFishPlace()
    -- UIModule.RemoveDialogRecord(Constants.UITypeIds.UIActionDungoenCollectionDialog)
    xTry(function()
        local storeData = CfUtils.GetLocalData("FISHING_PLACE_UNLOCKED", "")
        local t = {}
        if not string.isEmpty(storeData) then
            t = table.deserialize(storeData)
        end
        --- {['1] = 1, num = 1} example
        local hasChanged = false
        if t[tostring(self._fishingPlaceVo.id)] and checkNumber(t[tostring(self._fishingPlaceVo.id)]) == 1 then
            ---存在解锁的鱼场
            t[tostring(self._fishingPlaceVo.id)] = 0
            if checkNumber(t.num) > 0 then
                t.num = checkNumber(t.num) - 1
            end
        end
        CfUtils.WriteLocalData("FISHING_PLACE_UNLOCKED", table.serialize(t))
        GameUtils.SetRedPointNum(Constants.RedPointConst.PhoneFishPlaceUnlocked , checkNumber(t.num))
        GameUtils.InvokeRedPointCallBack(Constants.RedPointConst.PhoneFishPlaceUnlocked)
    end)
    local FishingMgr = import('Game.UI.Fishing.FishingMgr')
    FishingMgr:GetInstance():EnranceFishPlace(self._fishingPlaceVo.id)
    --[[
    self._co = cs_coroutine.start(function()
        local sceneManagement = SceneManagement:GetInstance()
        local ConstantsFishing = import('Game.UI.Fishing.ConstantsFishing')
        local Yielders = CS.Engine.Lib.Yielders

        Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, false)
        sceneManagement:AppendScene(ConstantsFishing.FishSceneId, true)
        while not sceneManagement:GetAppendingScene(ConstantsFishing.FishSceneId) do
            coroutine.yield(Yielders.EndOfFrame)
