        UIModule.OpenDialog({ id = Constants.UITypeIds.UIFishPoolGoFishingDialog, parameters = {fishingPlaceId = self._fishingPlaceVo.id}}, {
            {id = Constants.UITypeIds.UIFishPoolMainDialog}
        })
    end)
    ]]
end

function UIFishPlaceNode:OnDestroy()
    GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.PhoneFishPlaceUnlocked)
    if self._co then 
        cs_coroutine.stop(self._co)
        self._co = nil
    end
    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
        self._timeDown = nil
    end
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIFishPlaceNode
